import itertools
import math

def is_perfect_square(k):
    if k < 1:
        return False
    sqrt_k = int(math.isqrt(k))
    return sqrt_k * sqrt_k == k

def solve_cool_integer(n):
    """
    Checks if n is a cool integer using backtracking search.
    Returns (True, permutation) if cool, or (False, None) otherwise.
    """
    nums = list(range(1, n + 1))

    # Backtracking helper function
    def find_permutation(current_permutation, current_sum, available_nums):
        if len(current_permutation) == n:
            return current_permutation

        for x in available_nums:
            next_sum = current_sum + x

            # Check the cool integer condition: the partial sum must NOT be a perfect square
            if not is_perfect_square(next_sum):
                # If valid, recurse
                new_available = available_nums - {x}
                result = find_permutation(
                    current_permutation + [x], 
                    next_sum, 
                    new_available
                )
                if result is not None:
                    return result

        return None

    # Start the search
    # We must try starting with every possible number since the starting sum is S_1 = x_1
    for start_x in nums:
        if is_perfect_square(start_x):
            continue # Prune immediately if the first element is a square

        available = set(nums) - {start_x}
        permutation = find_permutation([start_x], start_x, available)

        if permutation is not None:
            return True, permutation

    return False, None

# Test for n=1 up to n=15
results = {}
for n in range(1, 16):
    is_cool, permutation = solve_cool_integer(n)
    results[n] = (is_cool, permutation)

print("--- Test Results for n=1 to n=15 ---")
for n, (is_cool, perm) in results.items():
    if is_cool:
        print(f"n={n}: Cool. Permutation: {perm}")
    else:
        print(f"n={n}: Not Cool.")

